/* Web Push worker — "แจ้งเตือนถาวร".
 * Deliberately separate from the app-shell service worker generated by
 * vite-plugin-pwa: it is registered under the narrow `/push/` scope so both
 * workers coexist, and it never touches Cache Storage.
 */
self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));

self.addEventListener("push", (event) => {
  let data = {};
  try { data = event.data ? event.data.json() : {}; } catch { data = { body: event.data && event.data.text() }; }
  const title = data.title || "FILM SHOP";
  // ปุ่มจัดการในตัวแจ้งเตือน — เปิดรายการ / รับเรื่อง / อ่านแล้ว
  const actions = [{ action: "open", title: "เปิดรายการ" }];
  if (data.notification_id) {
    actions.push({ action: "ack", title: "รับเรื่อง" });
    actions.push({ action: "read", title: "อ่านแล้ว" });
  }
  const options = {
    body: data.body || "",
    icon: data.icon || "/icons/staff-192.png",
    badge: "/icons/staff-192.png",
    tag: data.tag || "fs-notify",
    renotify: true,
    // Persistent: stays on screen until tapped, and vibrates on Android.
    requireInteraction: data.requireInteraction !== false,
    vibrate: [180, 80, 180],
    actions: actions.slice(0, 2 + (data.notification_id ? 1 : 0)),
    data: {
      url: data.url || "/film-shop",
      notificationId: data.notification_id || null,
      ackUrl: data.ack_url || null,
      ...(data.data || {}),
    },
  };
  event.waitUntil(self.registration.showNotification(title, options));
});

/** เรียก edge function ด้วยกุญแจของ subscription เครื่องนี้ (ไม่มี JWT ใน worker) */
async function sendAction(d, action) {
  if (!d || !d.ackUrl || !d.notificationId) return false;
  try {
    const sub = await self.registration.pushManager.getSubscription();
    if (!sub) return false;
    const raw = sub.toJSON();
    const res = await fetch(d.ackUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        endpoint: sub.endpoint,
        auth: raw && raw.keys ? raw.keys.auth : "",
        notification_id: d.notificationId,
        action,
      }),
    });
    return res.ok;
  } catch { return false; }
}

self.addEventListener("notificationclick", (event) => {
  const d = event.notification.data || {};
  const act = event.action;
  event.notification.close();

  // "อ่านแล้ว" / "รับเรื่อง" — จัดการจากตัวแจ้งเตือนโดยไม่ต้องเปิดแอป
  if (act === "read" || act === "ack") {
    event.waitUntil((async () => {
      const ok = await sendAction(d, act);
      const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      for (const c of all) c.postMessage({ type: "fs-push-action", action: act, id: d.notificationId, ok });
      if (!ok) {
        await self.registration.showNotification("บันทึกไม่สำเร็จ", {
          body: "แตะเพื่อเปิดศูนย์แจ้งเตือนแล้วลองใหม่",
          tag: "fs-notify-error",
          data: { url: d.url || "/film-shop/app?p=alerts" },
        });
      }
    })());
    return;
  }

  const target = d.url || "/film-shop";
  event.waitUntil((async () => {
    // เปิดรายการ = ทำเครื่องหมายอ่านแล้วให้อัตโนมัติ
    if (d.notificationId) await sendAction(d, "read");
    const all = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
    for (const client of all) {
      if (client.url.includes(self.location.origin)) {
        await client.focus();
        if ("navigate" in client) { try { await client.navigate(target); } catch { /* keep focus */ } }
        return;
      }
    }
    await self.clients.openWindow(target);
  })());
});
